{
	const auto Value{UAlsVector::ClampMagnitude012D(ActionValue.Get<FVector2D>())};

	auto ViewRotation{GetViewState().Rotation};

	if (IsValid(GetController()))
	{
		// Use exact camera rotation instead of target rotation whenever possible.

		FVector ViewLocation;
		GetController()->GetPlayerViewPoint(ViewLocation, ViewRotation);
	}

	const auto ForwardDirection{UAlsVector::AngleToDirectionXY(UE_REAL_TO_FLOAT(ViewRotation.Yaw))};
	const auto RightDirection{UAlsVector::PerpendicularCounterClockwiseXY(ForwardDirection)};

	AddMovementInput(ForwardDirection * Value.Y + RightDirection * Value.X);

static constexpr inline void SinCos(std::decay_t<T>* ScalarSin, std::decay_t<T>* ScalarCos, T  Value )
{
	// Map Value to y in [-pi,pi], x = 2*pi*quotient + remainder.
	T quotient = (UE_INV_PI*0.5f)*Value;
	if (Value >= 0.0f)
	{
		quotient = (T)((int64)(quotient + 0.5f));
	}
	else
	{
		quotient = (T)((int64)(quotient - 0.5f));
	}
	T y = Value - UE_TWO_PI * quotient;

	// Map y to [-pi/2,pi/2] with sin(y) = sin(Value).
	T sign;
	if (y > UE_HALF_PI)
	{
		y = UE_PI - y;
		sign = -1.0f;
	}
	else if (y < -UE_HALF_PI)
	{
		y = -UE_PI - y;
		sign = -1.0f;
	}
	else
	{
		sign = +1.0f;
	}

	T y2 = y * y;

	// 11-degree minimax approximation
	*ScalarSin = ( ( ( ( (-2.3889859e-08f * y2 + 2.7525562e-06f) * y2 - 0.00019840874f ) * y2 + 0.0083333310f ) * y2 - 0.16666667f ) * y2 + 1.0f ) * y;

	// 10-degree minimax approximation
	T p = ( ( ( ( -2.6051615e-07f * y2 + 2.4760495e-05f ) * y2 - 0.0013888378f ) * y2 + 0.041666638f ) * y2 - 0.5f ) * y2 + 1.0f;
	*ScalarCos = sign*p;

template<typename T>
inline TVector<T> TVector<T>::GetClampedToMaxSize(T MaxSize) const
{
    if (MaxSize < UE_KINDA_SMALL_NUMBER)
    {
        return ZeroVector;
    }

    const T VSq = SizeSquared();
    if (VSq > FMath::Square(MaxSize))
    {
        const T Scale = MaxSize * FMath::InvSqrt(VSq);
        return TVector<T>(X*Scale, Y*Scale, Z*Scale);
    }
    else
    {
        return *this;
    }	
}

